UPDATE trade_pay
SET qr_code_url = #{qrCodeUrl}, status = 'unpaid', update_time = NOW()
WHERE out_trade_no = #{outTradeNo}

mapper.select:
SELECT pay_id, order_id, out_trade_no, pay_channel, pay_amount, qr_code_url,
       status, paid_at, expire_at, create_time, update_time, fail_reason
FROM trade_pay
WHERE out_trade_no = #{outTradeNo}
AND tenant_id = #{tid}

SELECT order_id, biz_type, pay_user_id, pay_channel, pay_amount, status
FROM trade_pay
WHERE out_trade_no = #{outTradeNo}
